INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('79b7e0cb-da66-4450-8acc-fc19c16c5348', 'b2b2b2b2-3030-4000-8000-000000000002', 24, 'Dia 24 — Propósito na dor', 'Semana 4: Integrar', '{"pch": "Todas as coisas cooperam para o bem\u2026 Sua dor tem prop\u00f3sito, mesmo quando n\u00e3o parece.", "verse": "Rm 8,28", "lectio": "Leia Rm 8,28-30. O plano de Deus.", "practice": "Escreva como sua dor pode servir a outra pessoa.", "question": "Que sentido voc\u00ea encontra na sua hist\u00f3ria?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;